import { useMemo } from "react";

export function CurrencyFormatting({
  amount = {{amount}},
  locale = "{{locale}}",
  showCode = {{showCode}},
  accent = "{{accent}}",
}) {
  const value = useMemo(() => {
    const currency = { "en-US": "USD", "de-DE": "EUR", "ja-JP": "JPY" }[locale] || "USD";
    return new Intl.NumberFormat(locale, { style: "currency", currency, currencyDisplay: showCode ? "code" : "symbol" }).format(amount);
  }, [amount, locale, showCode]);
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099", wordBreak: "break-word" }}>new Intl.NumberFormat("{locale}", {"{"} style: "currency" {"}"})</p>
      <p style={{ margin: 0, fontSize: 28, fontWeight: 800, color: accent }}>{value}</p>
    </div>
  );
}
